// C++ 侧修复（需重建 Bridge DLL）
void UBPBridge::ClearGraphNodes(UEdGraph* Graph) {
    for (UEdGraphNode* Node : Graph->Nodes) {
        Node->DestroyNode();  // ⚠️ 必须调用
    }
    Graph->Nodes.Empty();
}

